-- ============================================================================
-- IMPORTACION DE HUESPEDES HISTORICOS -- Hotel Jorge Chavez
-- ============================================================================
-- Extraidos y deduplicados desde la hoja 'Reservas' del Excel legado
-- (CONTROL_HABITACIONES_JORGE_CHAVEZ). 1318 huespedes unicos.
--
-- Se omitieron (quedaron fuera, sin tocar el sistema):
--   - Reservas sin ningun numero de documento (nro_doc es obligatorio).
--   - Filas donde el 'cliente' era en realidad una agencia/empresa sin nombre
--     de persona (ej. 'PERU LEGENDARIO', 'TUMI TRAVEL').
--
-- ON CONFLICT DO NOTHING: si un huesped con el mismo (tipo_doc, nro_doc) ya
-- existe en el hotel (ej. cargado a mano durante pruebas), no se duplica ni
-- se pisa su informacion -- simplemente se salta esa fila.
-- ============================================================================

begin;

on conflict (hotel_id, tipo_doc, nro_doc) do nothing;

commit;
